filament_start_gcode:
; filament start gcode
{if  (bed_temperature[current_extruder] >55)||(bed_temperature_initial_layer[current_extruder] >55)}M106 P3 S200
{elsif(bed_temperature[current_extruder] >50)||(bed_temperature_initial_layer[current_extruder] >50)}M106 P3 S150
{elsif(bed_temperature[current_extruder] >45)||(bed_temperature_initial_layer[current_extruder] >45)}M106 P3 S50
{endif}

{if activate_air_filtration[current_extruder] && support_air_filtration}
M106 P3 S{during_print_exhaust_fan_speed_num[current_extruder]} 
{endif}

Snapmaker U1 (0.2 nozzle).change_filament_gcode:
;===== date: 20261003 =====================
; Change Tool[previous_extruder] -> Tool[next_extruder] (layer [layer_num])
; max_layer_z [max_layer_z]
; max_print_height [max_print_height]
; print_sequence [print_sequence]

{
local move_z = 1.5;
local max_speed_toolchange = 350.0;
local wait_for_extruder_temp = true;
position[2] = position[2] + 2.0;
local speed_toolchange = max_speed_toolchange;

if travel_speed < max_speed_toolchange then
      speed_toolchange = travel_speed;
endif

if print_sequence == "by object" then

    move_z = max_print_height;
    if max_layer_z < ((max_print_height - z_offset) - 2) then
        move_z = z_offset + min(((max_layer_z - z_offset) + 2), max_print_height);
    endif

"G90
G1 Z" + move_z + " F600
";

else

"G91
G1 Z" + move_z + " F600
G90
";

endif
"G1 F" + (speed_toolchange * 60) + "
";
if wait_for_extruder_temp and not((layer_num < 0) and (next_extruder == initial_tool)) then
      "
";
      "; " + layer_num + "
";
      if layer_num == 0 then
            "M104 S" + first_layer_temperature[next_extruder] + " T" + next_extruder + "
";
      else
            "M104 S" + temperature[next_extruder] + " T" + next_extruder + "
";
      endif
endif
"M400" + "
";
"T" + next_extruder + "
";
if filament_type[next_extruder] == "PVA" then
"SET_VELOCITY_LIMIT ACCEL=3000
";
else
endif
if previous_extruder != next_extruder and initial_extruder != next_extruder then
"SM_PRINT_PREEXTRUDE_FILAMENT INDEX=" + next_extruder + "
";
endif
"G90
";
}

